-- Compras de la organización 3 · 2 de 4: detalle de las compras, de los archivos
--   «ACT_DETALLE_COMPRAS_MED.xls» (2413 artículos de las compras de medicamentos) y
--   «ACT_DETALLE_COMPRAS_VARIAS.xls» (460 líneas de las compras varias de 3-02).
--   1. Una línea que ya existe en la compra (mismo número de línea) se actualiza; si no, se crea.
--   2. Columnas nuevas:
--      compra_articulos: producto_codigo (CODIGO_PRODUCTO), producto_anterior (PRODUCTO),
--        costo_unitario_compra, unidades_compra, costo_total_pre, regalias, costo_unitario_mi,
--        costo_total_mi, incluir_compra (S/N) y formato_fecha.
--      compra_items: aplica_iva_imp (S/N).
--   Los productos de la organización 3 aún no están en el sistema: cada artículo guarda el código del
--   producto y queda sin ligar (producto_id ya no es obligatorio); cuando se cree el producto con ese
--   código en la localidad, los artículos se ligan solos. LOTE = serie (lote); fechas de fabricación y de
--   vencimiento (control de fecha si trae vencimiento); INVENTARIADA S/N. En una compra en dólares el
--   costo es el de moneda internacional (COSTO_UNITARIO_MI). El costo total de la línea lo calcula la base
--   de datos (cantidad × costo unitario − descuento); el del archivo queda en costo_total_pre y costo_total_mi.
--   Las líneas se ligan a la compra por su origen y número del sistema anterior (script 89). Las líneas de
--   una compra varia que se fusionó con su compra de medicamentos no se agregan: ese detalle ya está en los
--   artículos de la compra.
--   Líneas con cantidad 0 (no se migran): 3-01 compra 385 línea 1; 3-01 compra 385 línea 4.
--   
--   Puede ejecutarse de nuevo: la segunda vez solo actualiza.
-- Se ejecuta después del script 89.

alter table public.compra_articulos alter column producto_id drop not null;
alter table public.compra_articulos add column if not exists producto_codigo text;
alter table public.compra_articulos add column if not exists producto_anterior integer;
alter table public.compra_articulos add column if not exists costo_unitario_compra numeric;
alter table public.compra_articulos add column if not exists unidades_compra numeric;
alter table public.compra_articulos add column if not exists costo_total_pre numeric;
alter table public.compra_articulos add column if not exists regalias numeric;
alter table public.compra_articulos add column if not exists costo_unitario_mi numeric;
alter table public.compra_articulos add column if not exists costo_total_mi numeric;
alter table public.compra_articulos add column if not exists incluir_compra boolean;
alter table public.compra_articulos add column if not exists formato_fecha text;
alter table public.compra_items add column if not exists aplica_iva_imp boolean;

-- Producto nuevo (o con su código corregido): se liga a los artículos de compra que lo esperaban.
create or replace function public.ligar_articulos_producto() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  perform set_config('fin.inventario', 'si', true);
  update public.compra_articulos a set producto_id = new.id
  from public.compras c
  where c.id = a.compra_id and a.producto_id is null and c.localidad_id = new.localidad_id
    and ((a.producto_codigo is not null and upper(a.producto_codigo) = upper(new.codigo_producto))
      or (a.producto_codigo is null and a.producto_anterior = new.codigo));
  perform set_config('fin.inventario', '', true);
  return null;
end;
$$;
drop trigger if exists productos_ligar_articulos on public.productos;
create trigger productos_ligar_articulos after insert or update of codigo_producto, codigo on public.productos
  for each row execute function public.ligar_articulos_producto();
revoke execute on function public.ligar_articulos_producto() from public, anon, authenticated;

do $migra$
declare
  v_org bigint;
  v_a_nuevos integer := 0;
  v_a_act integer := 0;
  v_i_nuevos integer := 0;
  v_i_act integer := 0;
  v_a_sin integer;
  v_i_sin integer;
  v_i_fus integer;
  v_ligados integer;
begin
  select id into v_org from public.organizaciones where codigo = 3;
  if v_org is null then raise exception 'No existe la organización 3.'; end if;

  drop table if exists m_art;
  create temp table m_art (loc integer, compra integer, linea integer, producto integer, codigo text, lote text, cantidad numeric, costo_total numeric,
    costo_unitario numeric, fecha_vencimiento date, costo_unitario_compra numeric, unidades_compra numeric, costo_total_pre numeric, exento boolean,
    incluir boolean, regalias numeric, inventariada boolean, fecha_fabricacion date, costo_unitario_mi numeric, costo_total_mi numeric, descuento numeric,
    formato_fecha text);
  drop table if exists m_items;
  create temp table m_items (loc integer, compra integer, linea integer, descripcion text, cantidad numeric, costo_total numeric, aplica_iva_imp boolean);

  select count(*) into v_a_sin from m_art m join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
  where not exists (select 1 from public.compras c where c.localidad_id = l.id and c.origen_anterior = 'MEDICAMENTOS' and c.compra_anterior = m.compra);
  select count(*) into v_i_sin from m_items m join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
  where not exists (select 1 from public.compras c where c.localidad_id = l.id and ((c.origen_anterior = 'VARIAS' and c.compra_anterior = m.compra) or c.compra_varia_anterior = m.compra));
  select count(*) into v_i_fus from m_items m join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
  where exists (select 1 from public.compras c where c.localidad_id = l.id and c.compra_varia_anterior = m.compra);

  -- Las validaciones de la pantalla (producto obligatorio, compra anulada) se suspenden durante la carga.
  alter table public.compra_articulos disable trigger compra_articulos_validar;
  alter table public.compra_items disable trigger compra_items_validar;
  with x as (
           inventario, exento, inventariado, fecha_fabricacion, fecha_vencimiento, control_fecha, costo_unitario_compra, unidades_compra,
           costo_total_pre, regalias, costo_unitario_mi, costo_total_mi, incluir_compra, formato_fecha)
    select c.id, m.linea,
           (select p.id from public.productos p where p.localidad_id = c.localidad_id
              and ((m.codigo is not null and upper(p.codigo_producto) = upper(m.codigo)) or (m.codigo is null and p.codigo = m.producto)) limit 1),
           m.codigo, m.producto, upper(m.lote), m.cantidad,
           case when mo.iso = 'USD' then coalesce(m.costo_unitario_mi, m.costo_unitario) else m.costo_unitario end, m.descuento, 0,
           true, coalesce(m.exento, false), coalesce(m.inventariada, false), m.fecha_fabricacion, m.fecha_vencimiento, m.fecha_vencimiento is not null,
           m.costo_unitario_compra, m.unidades_compra, m.costo_total_pre, m.regalias, m.costo_unitario_mi, m.costo_total_mi, m.incluir, m.formato_fecha
    from m_art m
    join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
    join public.compras c on c.localidad_id = l.id and c.origen_anterior = 'MEDICAMENTOS' and c.compra_anterior = m.compra
    left join public.monedas mo on mo.id = c.moneda_id
    on conflict (compra_id, linea) do update set
      producto_id = coalesce(excluded.producto_id, public.compra_articulos.producto_id), producto_codigo = excluded.producto_codigo,
      producto_anterior = excluded.producto_anterior, serie = excluded.serie, cantidad = excluded.cantidad, costo_unitario = excluded.costo_unitario,
      descuento = excluded.descuento, exento = excluded.exento, inventariado = excluded.inventariado,
      fecha_fabricacion = excluded.fecha_fabricacion, fecha_vencimiento = excluded.fecha_vencimiento, control_fecha = excluded.control_fecha,
      costo_unitario_compra = excluded.costo_unitario_compra, unidades_compra = excluded.unidades_compra, costo_total_pre = excluded.costo_total_pre,
      regalias = excluded.regalias, costo_unitario_mi = excluded.costo_unitario_mi, costo_total_mi = excluded.costo_total_mi,
      incluir_compra = excluded.incluir_compra, formato_fecha = excluded.formato_fecha
    returning (xmax = 0) as nuevo)
  select count(*) filter (where nuevo), count(*) filter (where not nuevo) into v_a_nuevos, v_a_act from x;
  with x as (
    select c.id, m.linea, upper(coalesce(m.descripcion, 'SIN DESCRIPCIÓN')), coalesce(m.cantidad, 1), coalesce(m.costo_total, 0), m.aplica_iva_imp
    from m_items m
    join public.localidades l on l.organizacion_id = v_org and l.correlativo = m.loc
    join public.compras c on c.localidad_id = l.id and c.origen_anterior = 'VARIAS' and c.compra_anterior = m.compra
    on conflict (compra_id, linea) do update set
      descripcion = excluded.descripcion, cantidad = excluded.cantidad, costo_total = excluded.costo_total, aplica_iva_imp = excluded.aplica_iva_imp
    returning (xmax = 0) as nuevo)
  select count(*) filter (where nuevo), count(*) filter (where not nuevo) into v_i_nuevos, v_i_act from x;
  alter table public.compra_articulos enable trigger compra_articulos_validar;
  alter table public.compra_items enable trigger compra_items_validar;
  select count(*) into v_ligados from public.compra_articulos a join public.compras c on c.id = a.compra_id
  where c.organizacion_id = v_org and c.origen_anterior = 'MEDICAMENTOS' and a.producto_id is not null;

  raise notice '%', format('Detalle de compras de la organización 3: artículos %s nuevos y %s actualizados (%s ligados a su producto; los demás esperan el producto); líneas de compras varias %s nuevas y %s actualizadas.%s%s',
    v_a_nuevos, v_a_act, v_ligados, v_i_nuevos, v_i_act,
    case when v_a_sin > 0 then format(' %s artículos de compras que no existen (omitidos).', v_a_sin) else '' end,
    case when v_i_fus > 0 then format(' %s líneas de compras varias que son copia de una compra de medicamentos no se agregan (su detalle ya está en los artículos).', v_i_fus) else '' end,
    case when v_i_sin > 0 then format(' %s líneas de compras varias que no existen (omitidas).', v_i_sin) else '' end);
  drop table m_art;
  drop table m_items;
end;
$migra$;

notify pgrst, 'reload schema';
